// правка 44: библиотека выученного -- перенос в новый мир. Мир текста: счёт органов языка (длины, слова, разреженные,
// частоты знаков), прочитанный текст для памяти совпадений, веса смесителя, какие органы живы, связи частей с органами и
// их веса. Мир тела: модель мотора (веса и средние входов) и связи моторных частей.
const mapOut = (m) => { const o = []; for (const [k, e] of m) { const sp = []; for (let c = 0; c < CH; c++) if (e.n[c]) sp.push(c, e.n[c]); o.push([k, e.tot, e.u, sp]); } return o; };
