  const slOf = (name) => (name[0] === 'L' ? +name.slice(1) : name === 'WA' ? CS.WA : name === 'WB' ? CS.WB : name === 'MT' ? CS.MT : name === 'NN' ? CS.NN : CS.X[CS.XT.indexOf(+name.slice(1))]);
